# CSV → DataFrame 변환
df = pd.read_csv(StringIO(log_data))

# 0번째, 7번째 컬럼 선택(각각 시간, 포탑 X좌표)
time = df.iloc[:, 0].values.reshape(-1, 1)      # 독립변수 X
turret_x = df.iloc[:, 7].values.reshape(-1, 1)  # 종속변수 y

# 선형회귀 모델 생성 및 학습
model = LinearRegression()
model.fit(time, turret_x)

# 회귀계수(기울기, 절편)
slope = model.coef_[0][0]      # 각속도(기울기)
intercept = model.intercept_[0]
r2 = r2_score(turret_x, model.predict(time))

print(f" 회귀식: turret_x = {slope:.6f} * time + {intercept:.6f}")
print(f" 결정계수 (R²): {r2:.6f}")
print(f" 포탑 각속도(기울기): {slope:.6f} (단위: degree/s)")

# 시각화
plt.figure(figsize=(8,5))
plt.scatter(time, turret_x, s=10, label="Actual Data", alpha=0.6)
plt.plot(time, model.predict(time), color='red', linewidth=2, label="Linear Fit")
plt.title("Turret X Position vs Time")
plt.xlabel("Time (s)")
plt.ylabel("Turret X Position(Degree)")
plt.legend()
plt.grid(True)
plt.show()

# 각속도 데이터프레임 생성 (선형근사 기반)
angular_velocity_df = pd.DataFrame({
    'time': df.iloc[:, 0],
    'predicted_turret_x': model.predict(time).flatten(),
    'angular_velocity': np.gradient(model.predict(time).flatten(), df.iloc[:, 0])
})

# 확인용 출력
print("\n   Angular Velocity Data (앞부분):")
print(angular_velocity_df.head())       # 